CREATE TABLE libraries (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, description VARCHAR(500), library_type VARCHAR(16) NOT NULL, privacy VARCHAR(16) NOT NULL, password_hash VARCHAR(255), minimum_age SMALLINT NOT NULL, metadata_language VARCHAR(16) NOT NULL, metadata_region VARCHAR(8), is_active BOOLEAN NOT NULL DEFAULT TRUE, scan_enabled BOOLEAN NOT NULL DEFAULT TRUE, created_by VARCHAR(36) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, last_scan_at VARCHAR(40), last_successful_scan_at VARCHAR(40), deleted_at VARCHAR(40), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE library_paths (id VARCHAR(36) PRIMARY KEY, library_id VARCHAR(36) NOT NULL, path TEXT NOT NULL, normalized_path VARCHAR(1024) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, status VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE', created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, last_scan_at VARCHAR(40), UNIQUE KEY uq_library_path(library_id,normalized_path), FOREIGN KEY(library_id) REFERENCES libraries(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE scan_jobs (id VARCHAR(36) PRIMARY KEY, library_id VARCHAR(36) NOT NULL, status VARCHAR(32) NOT NULL, scan_type VARCHAR(16) NOT NULL, started_at VARCHAR(40), finished_at VARCHAR(40), discovered_files BIGINT NOT NULL DEFAULT 0, processed_files BIGINT NOT NULL DEFAULT 0, matched_files BIGINT NOT NULL DEFAULT 0, unmatched_files BIGINT NOT NULL DEFAULT 0, skipped_files BIGINT NOT NULL DEFAULT 0, removed_files BIGINT NOT NULL DEFAULT 0, failed_files BIGINT NOT NULL DEFAULT 0, progress DOUBLE NOT NULL DEFAULT 0, error_message TEXT, created_by VARCHAR(36) NOT NULL, created_at VARCHAR(40) NOT NULL, discovery_ms BIGINT NOT NULL DEFAULT 0, matching_ms BIGINT NOT NULL DEFAULT 0, persistence_ms BIGINT NOT NULL DEFAULT 0, tmdb_requests BIGINT NOT NULL DEFAULT 0, tmdb_cache_hits BIGINT NOT NULL DEFAULT 0, db_batches BIGINT NOT NULL DEFAULT 0, INDEX idx_scans_library(library_id,created_at), FOREIGN KEY(library_id) REFERENCES libraries(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE media_items (id VARCHAR(36) PRIMARY KEY, library_id VARCHAR(36) NOT NULL, media_type VARCHAR(16) NOT NULL, tmdb_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, original_title VARCHAR(255), overview TEXT, original_language VARCHAR(16), release_date VARCHAR(40), year SMALLINT, poster_path VARCHAR(255), backdrop_path VARCHAR(255), rating DOUBLE, vote_count BIGINT, popularity DOUBLE, adult BOOLEAN NOT NULL DEFAULT FALSE, metadata_language VARCHAR(16) NOT NULL, metadata_source VARCHAR(16) NOT NULL, metadata_fetched_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_media_item(library_id,media_type,tmdb_id), INDEX idx_media_items_library(library_id,media_type), INDEX idx_media_items_tmdb(tmdb_id), FOREIGN KEY(library_id) REFERENCES libraries(id)) ENGINE=InnoDB;
CREATE TABLE media_files (id VARCHAR(36) PRIMARY KEY, library_id VARCHAR(36) NOT NULL, library_path_id VARCHAR(36) NOT NULL, media_item_id VARCHAR(36), tv_episode_id VARCHAR(36), absolute_path VARCHAR(700) NOT NULL, relative_path TEXT NOT NULL, filename VARCHAR(1024) NOT NULL, extension VARCHAR(16) NOT NULL, file_size BIGINT NOT NULL, modified_at VARCHAR(40) NOT NULL, filesystem_identity VARCHAR(255), content_type VARCHAR(16) NOT NULL, scan_status VARCHAR(32) NOT NULL, identification_status VARCHAR(32) NOT NULL, normalized_title VARCHAR(255), parsed_year SMALLINT, parsed_season SMALLINT, parsed_episode SMALLINT, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, last_seen_at VARCHAR(40) NOT NULL, missing_since VARCHAR(40), UNIQUE KEY uq_media_file(library_id,absolute_path), INDEX idx_media_files_library(library_id), INDEX idx_media_files_path(library_path_id), INDEX idx_media_files_identification(identification_status), INDEX idx_media_files_seen(last_seen_at), INDEX idx_media_files_modified(modified_at), FOREIGN KEY(library_id) REFERENCES libraries(id), FOREIGN KEY(library_path_id) REFERENCES library_paths(id), FOREIGN KEY(media_item_id) REFERENCES media_items(id)) ENGINE=InnoDB;
CREATE TABLE movies (media_item_id VARCHAR(36) PRIMARY KEY, runtime INT, status VARCHAR(64), tagline VARCHAR(500), collection_tmdb_id BIGINT, collection_name VARCHAR(255), production_companies JSON, production_countries JSON, spoken_languages JSON, external_ids JSON, keywords JSON, FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tv_shows (media_item_id VARCHAR(36) PRIMARY KEY, last_air_date VARCHAR(40), status VARCHAR(64), show_type VARCHAR(64), number_of_seasons INT, number_of_episodes INT, networks JSON, creators JSON, production_companies JSON, external_ids JSON, FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tv_seasons (id VARCHAR(36) PRIMARY KEY, tv_show_id VARCHAR(36) NOT NULL, tmdb_id BIGINT, season_number INT NOT NULL, name VARCHAR(255), overview TEXT, air_date VARCHAR(40), poster_path VARCHAR(255), episode_count INT, UNIQUE KEY uq_season(tv_show_id,season_number), FOREIGN KEY(tv_show_id) REFERENCES media_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tv_episodes (id VARCHAR(36) PRIMARY KEY, tv_show_id VARCHAR(36) NOT NULL, season_id VARCHAR(36) NOT NULL, tmdb_id BIGINT, season_number INT NOT NULL, episode_number INT NOT NULL, name VARCHAR(255), overview TEXT, air_date VARCHAR(40), still_path VARCHAR(255), rating DOUBLE, vote_count BIGINT, runtime INT, UNIQUE KEY uq_episode(season_id,episode_number), INDEX idx_episodes_show_numbers(tv_show_id,season_number,episode_number), FOREIGN KEY(tv_show_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(season_id) REFERENCES tv_seasons(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE genres (id VARCHAR(36) PRIMARY KEY, tmdb_id BIGINT NOT NULL UNIQUE, name VARCHAR(128) NOT NULL) ENGINE=InnoDB; CREATE TABLE media_genres (media_item_id VARCHAR(36) NOT NULL, genre_id VARCHAR(36) NOT NULL, PRIMARY KEY(media_item_id,genre_id), FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(genre_id) REFERENCES genres(id)) ENGINE=InnoDB;
CREATE TABLE people (id VARCHAR(36) PRIMARY KEY, tmdb_id BIGINT NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, profile_path VARCHAR(255), known_for_department VARCHAR(128)) ENGINE=InnoDB; CREATE TABLE credits (id VARCHAR(36) PRIMARY KEY, media_item_id VARCHAR(36) NOT NULL, person_id VARCHAR(36) NOT NULL, credit_type VARCHAR(16) NOT NULL, character_name VARCHAR(255), job VARCHAR(255), department VARCHAR(128), credit_order INT, signature VARCHAR(64) NOT NULL, UNIQUE KEY uq_credit(media_item_id,signature), INDEX idx_credits_media(media_item_id), INDEX idx_credits_person(person_id), FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES people(id)) ENGINE=InnoDB;
CREATE TABLE metadata_cache (provider VARCHAR(16) NOT NULL, request_key VARCHAR(512) NOT NULL, response_type VARCHAR(32) NOT NULL, entity_id BIGINT, language VARCHAR(16) NOT NULL, payload JSON NOT NULL, expires_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, PRIMARY KEY(provider,request_key,language)) ENGINE=InnoDB;
